function createWallet(start) {
    let balance = start;            // private: tashqaridan ko'rinmaydi

    return {
        deposit(amount) { balance += amount; },
        spend(amount) {
            if (amount > balance) return false;
            balance -= amount;
            return true;
        },
        getBalance() { return balance; },
    };
}

