function memoize(fn) {
    const cache = new Map();
    return function (n) {
        if (cache.has(n)) {
            return cache.get(n);
        }
        const value = fn(n);
        cache.set(n, value);
        return value;
    };
}

const fastSquare = memoize(slowSquare);
