function createEmitter() {
    const listeners = {};
    return {
        on(event, handler) {
            (listeners[event] ??= []).push(handler);
        },
        emit(event, data) {
            (listeners[event] ?? []).forEach((handler) => handler(data));
        },
    };
}

const emitter = createEmitter();
