function createStore(initialState) {
    let state = initialState;
    const subscribers = [];
    return {
        getState: () => state,
        setState(patch) {
            state = { ...state, ...patch };
            subscribers.forEach((fn) => fn(state));
        },
        subscribe(fn) {
            subscribers.push(fn);
        },
    };
}

