function createCache(ttl, getNow) {
    const store = new Map();
    return {
        set(key, value) {
            store.set(key, { value, expires: getNow() + ttl });
        },
        get(key) {
            const entry = store.get(key);
            if (!entry) return undefined;
            if (getNow() > entry.expires) {
                store.delete(key);
                return undefined;
            }
            return entry.value;
        },
    };
}

