    if (low > high) return -1;
    const mid = Math.floor((low + high) / 2);
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) return binarySearch(sorted, target, mid + 1, high);
    return binarySearch(sorted, target, low, mid - 1);
}

