function quickSort(list) {
    if (list.length <= 1) return list;
    const [pivot, ...rest] = list;
    const smaller = rest.filter((x) => x < pivot);
    const bigger = rest.filter((x) => x >= pivot);
    return [...quickSort(smaller), pivot, ...quickSort(bigger)];
}

